void schedule(steady_timer& t, std::chrono::milliseconds d) {
  t.expires_after(d);
  t.async_wait([&](error_code ec) { if (!ec) drain_once(&schedule); });
}
// drain_once delivers the oldest spool file; on failure it re-arms with d * 2,
// on success it removes the file and immediately schedules the next pass.
